#!/usr/bin/env bash
# RC-FSV-01 LOCAL SYNTHETIC ONLY: migration-from-zero schema comparison against actual PN-03 adapter expectations.
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/../../.." && pwd); BASE=$(mktemp -d /tmp/rc-fsv-drift.XXXXXX); DATA="$BASE/data"; SOCK="$BASE/socket"; PORT=55452; MIGRATION="$BASE/001_work_items.sql"
cleanup(){ sudo -u postgres -- /usr/lib/postgresql/16/bin/pg_ctl -D "$DATA" -m immediate stop >/dev/null 2>&1 || true; sudo -u postgres -- rm -rf "$BASE"; }; trap cleanup EXIT
sudo chown postgres:postgres "$BASE"; sudo -u postgres -- mkdir -p "$DATA" "$SOCK"; sudo -u postgres -- chmod 755 "$SOCK"; sudo chmod 711 "$BASE"; sudo cp "$ROOT/infra/pn03/migrations/001_work_items.sql" "$MIGRATION"; sudo chown postgres:postgres "$MIGRATION"; sudo -u postgres -- /usr/lib/postgresql/16/bin/initdb -D "$DATA" -A trust >/dev/null; sudo -u postgres -- /usr/lib/postgresql/16/bin/pg_ctl -D "$DATA" -o "-k $SOCK -p $PORT" -w start >/dev/null
sudo -u postgres -- createdb -h "$SOCK" -p "$PORT" rc_drift; sudo -u postgres -- psql -X -q -h "$SOCK" -p "$PORT" -d rc_drift -f "$MIGRATION"
COLS=$(sudo -u postgres -- psql -XAt -h "$SOCK" -p "$PORT" -d rc_drift -c "SELECT string_agg(column_name||':'||data_type,',' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_name='work_items'"); EXPECTED='id:text,tenant_id:text,state:text,version:integer,classification:text'; test "$COLS" = "$EXPECTED"; sudo -u postgres -- psql -XAt -h "$SOCK" -p "$PORT" -d rc_drift -c "SELECT conname FROM pg_constraint WHERE conrelid='work_items'::regclass ORDER BY conname" | grep -q 'work_items_pkey'; grep -q "work_items" "$ROOT/src/pn03/postgres-adapter.ts"; grep -q "tenant_id" "$ROOT/src/pn03/postgres-adapter.ts"; grep -q "ConcurrencyFailure" "$ROOT/src/pn03/postgres-adapter.ts"; echo "RC_SCHEMA_DRIFT=PASS columns=$COLS constraints=PASS migration_from_zero=PASS adapter_contract=PASS rls=NOT_APPLICABLE_TO_APPROVED_MIGRATION"
